@include('questions.math')<script>document.addEventListener('DOMContentLoaded',()=>{const type=document.querySelector('#type'),toggle=()=>{document.querySelector('#mc').style.display=type.value==='multiple_choice'?'block':'none';document.querySelector('#essay').style.display=type.value==='essay'?'grid':'none'};type.onchange=toggle;toggle();document.querySelectorAll('[data-insert]').forEach(b=>b.onclick=()=>{let e=document.getElementById(b.dataset.target),p=e.selectionStart;e.value=e.value.slice(0,p)+'$'+b.dataset.insert+'$'+e.value.slice(e.selectionEnd);e.dispatchEvent(new Event('input'))});document.querySelectorAll('.math-preview').forEach(p=>{let e=document.getElementById(p.dataset.source),draw=()=>{p.textContent=e.value;renderMathInElement(p,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false})};e.oninput=draw;draw()})})</script>@endsection
